    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A surprise twist: we skip the usual cathedral and wander the artisan lanes of San Blas instead.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper midday pause with plenty of vegetarian choices, right in the heart of the old town.",
      "must_do_id": null
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "The grand cathedral still fits, but now it comes after lunch when the light softens.",
      "must_do_id": null
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "An unexpected finish: the blinding white salt terraces, a photo spot nobody saw coming.",
      "must_do_id": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
